// TypeScript FoO function (in Code Repository)
import { Function, OntologyEdit, Objects } from '@foundry/functions-api';
import { Supplier } from '@my-company/ontology';

export class SupplierFunctions {
  // Computed attribute: composite risk score (0-100)
  @Function()
  computeCompositeRiskScore(supplier: Supplier): number {
    // Weighted scoring: delivery performance, financials, jurisdiction
    const deliveryScore = supplier.onTimeDeliveryRate * 40;  // 40% weight
    const financialScore = this.mapFinancialRating(supplier.creditRating) * 30; // 30%
    const jurisdictionScore = this.mapJurisdictionRisk(supplier.country) * 30; // 30%
    return deliveryScore + financialScore + jurisdictionScore;
  }

  // Computed attribute: risk band
  @Function()
  riskBand(supplier: Supplier): 'LOW' | 'MEDIUM' | 'HIGH' | 'CRITICAL' {
    const score = this.computeCompositeRiskScore(supplier);
    if (score >= 80) return 'LOW';
    if (score >= 60) return 'MEDIUM';
    if (score >= 40) return 'HIGH';
    return 'CRITICAL';
  }

  private mapFinancialRating(rating: string): number {
    const map: Record<string, number> = {
      'AAA': 100, 'AA': 90, 'A': 80, 'BBB': 70, 'BB': 50, 'B': 30
    };
    return map[rating] ?? 0;
  }

  private mapJurisdictionRisk(country: string): number {
    const highRisk = ['KP', 'IR', 'SY']; // OFAC restricted
    const medRisk = ['RU', 'BY', 'VE'];
    if (highRisk.includes(country)) return 0;
    if (medRisk.includes(country)) return 40;
    return 80;
  }
}

// Usage in Workshop: display supplier.riskBand() alongside stored properties
// Usage in AIP Logic prompt: '{Supplier.riskBand()}' in the prompt template
// Usage in OSDK: const band = await supplier.riskBand(); (returns typed union)
