import anthropic, base64
from PIL import ImageGrab  # for screenshot (pip install Pillow)
import pyautogui  # for executing mouse/keyboard actions

client = anthropic.Anthropic()

def take_screenshot_base64():
    img = ImageGrab.grab()
    import io
    buf = io.BytesIO()
    img.save(buf, format='PNG')
    return base64.standard_b64encode(buf.getvalue()).decode('utf-8')

def execute_action(action):
    if action['type'] == 'screenshot':
        return take_screenshot_base64()
    elif action['type'] == 'left_click':
        pyautogui.click(action['coordinate'][0], action['coordinate'][1])
    elif action['type'] == 'type':
        pyautogui.write(action['text'], interval=0.05)
    elif action['type'] == 'key':
        pyautogui.hotkey(*action['text'].split('+'))
    elif action['type'] == 'scroll':
        pyautogui.scroll(action['coordinate'][0], action['coordinate'][1])

# Computer Use agent loop
def run_computer_use_task(task: str):
    screenshot_b64 = take_screenshot_base64()

    messages = [{
        'role': 'user',
        'content': [
            {
                'type': 'image',
                'source': {'type': 'base64', 'media_type': 'image/png',
                           'data': screenshot_b64}
            },
            {'type': 'text', 'text': task}
        ]
    }]

    tools = [{
        'type': 'computer_20241022',
        'name': 'computer',
        'display_width_px': 1920,
        'display_height_px': 1080,
        'display_number': 1
    }]

    while True:
        response = client.messages.create(
            model='claude-opus-4-8',  # Computer Use requires Opus or similar capable model
            max_tokens=4096,
            tools=tools,
            messages=messages
        )

        if response.stop_reason == 'end_turn':
            return  # Task complete

        for block in response.content:
            if block.type == 'tool_use' and block.name == 'computer':
                action = block.input
                result = execute_action(action)
                # Add tool result and new screenshot to messages
                messages.append({'role': 'assistant', 'content': response.content})
                messages.append({'role': 'user', 'content': [{
                    'type': 'tool_result',
                    'tool_use_id': block.id,
                    'content': [{
                        'type': 'image',
                        'source': {'type': 'base64', 'media_type': 'image/png',
                                   'data': take_screenshot_base64()}
                    }]
                }]})
